package io.github.kirstenali.deepj.chatui;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Base64;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

/** Opt-in visual review of the production page using an image generated by the full desktop checkpoint test. */
@EnabledIfSystemProperty(named = "deepj.uiReviewImage", matches = ".+")
class ImageLayoutReviewTest extends ChatDesktopTestSupport {
    @Test void capturesImageControlsAndResultsAcrossTheExistingThemes() throws Exception {
        var fixture = open();
        try {
            verifyWithoutClosing(fixture, view ->
                    script(view, "setImageModel('SANA-Sprint 0.6B'); setStatus('Ready on Metal')"));
            ImageDesktopSnapshots.capture(fixture, "ready");
            verifyWithoutClosing(fixture, view -> script(view, "openImageSettings()"));
            ImageDesktopSnapshots.capture(fixture, "settings");
            verifyWithoutClosing(fixture, view ->
                    script(view, "closeSettings(); startImage('A red fox in a snowy forest',1)"));
            ImageDesktopSnapshots.capture(fixture, "generating");
            showImage(fixture);
            for (String theme : new String[]{"light", "dark", "warm", "ocean"}) {
                reviewTheme(fixture, theme);
            }
        } finally { verify(fixture, view -> {}); }
    }

    private static void reviewTheme(Fixture fixture, String theme) throws Exception {
        verifyWithoutClosing(fixture, view -> script(view, "setTheme('" + theme + "')"));
        ImageDesktopSnapshots.capture(fixture, "image-" + theme);
        verifyWithoutClosing(fixture, view -> script(view, "openImageSettings()"));
        ImageDesktopSnapshots.capture(fixture, "settings-" + theme);
        verifyWithoutClosing(fixture, view -> script(view, "closeSettings()"));
    }

    private static void showImage(Fixture fixture) throws Exception {
        byte[] png = Files.readAllBytes(Path.of(System.getProperty("deepj.uiReviewImage")));
        String uri = "data:image/png;base64," + Base64.getEncoder().encodeToString(png);
        verifyWithoutClosing(fixture, view -> {
            var window = (netscape.javascript.JSObject) script(view, "window");
            window.call("finishImage", 1, uri, 1024, 1024, 2, 42);
            script(view, "setGenerating(false); setBusy(false); setStatus('Ready on Metal')");
        });
        awaitScript(fixture, "document.querySelector('.generated-image').naturalWidth === 1024");
    }
}
